{
  "resources": [
    {
      "url": "https://www.dw.com/en/learn-german/nicos-weg/s-56841434",
      "title": "Nico's Weg – A1 (Deutsche Welle)",
      "description": "A free video-story German course: short episodes following someone arriving in Germany, with exercises after each one.",
      "howToUse": "Watch one episode before a session and note the phrases you almost understood — those are the ones to practise producing.",
      "summary": "Deutsche Welle's A1 course, told as a two-to-four-minute video story per episode with transcripts, optional German or English subtitles, and vocabulary and grammar exercises after each. Covers greetings, introductions, directions, shopping and ordering, which maps onto the early goals of a conversational path. Continues into A2 and B1 in the same format.",
      "goalTitles": [
        "Greet and introduce yourself",
        "Order food and drinks"
      ]
    },
    {
      "url": "https://www.easygerman.org/",
      "title": "Easy German (street interviews)",
      "description": "Unscripted street interviews with dual subtitles — real speech at real speed, on everyday topics.",
      "howToUse": "Use it for listening: play a clip twice, once with subtitles and once without, and write down one whole sentence you caught.",
      "summary": "A long-running YouTube project interviewing people on the street in German, with German and English subtitles on every clip. Episodes are topic-based (weekend plans, food, work) and feature regional accents and natural speed, which makes it the closest free approximation of the dinner-table listening a learner in Munich needs.",
      "goalTitles": [
        "Handle small talk about your weekend"
      ]
    },
    {
      "url": "https://yourdailygerman.com/dative-explained/",
      "title": "The German dative, explained",
      "description": "A long, plain-language explanation of what the dative is actually for, rather than a table to memorise.",
      "howToUse": "Read it when case endings start getting in the way of saying what you mean — not before.",
      "summary": "An essay-style grammar explainer covering the dative's role, the verbs and prepositions that take it, and why the usual tables mislead learners. Written conversationally with many example sentences, most drawn from everyday speech.",
      "goalTitles": []
    },
    {
      "url": "https://www.goethe.de/de/spr/ueb/led.html",
      "title": "Goethe-Institut listening exercises",
      "description": "Short graded listening exercises with answers, from the institute that writes the standard German exams.",
      "howToUse": "One exercise per session, at the level just above where you are comfortable.",
      "summary": "Free graded listening practice from the Goethe-Institut, organised by CEFR level, each with an audio clip, comprehension questions and answers. Useful as a calibration tool: the levels are the same ones used by the standard exams.",
      "goalTitles": [
        "Talk about your family"
      ]
    }
  ]
}
